import React, { useState } from "react";
import "./App.css";

function App() {
  const [query, setQuery] = useState("");
  const [disease, setDisease] = useState("");
  const [location, setLocation] = useState("");
  const [whatIf, setWhatIf] = useState("");

  const [data, setData] = useState(null);
  const [whatIfResult, setWhatIfResult] = useState("");

  const [loading, setLoading] = useState(false);
  const [whatIfLoading, setWhatIfLoading] = useState(false);

  // =========================
  // ANALYZE
  // =========================
  const handleAnalyze = async () => {
    setLoading(true);
    setData(null);
    setWhatIfResult("");

    try {
      const res = await fetch("http://127.0.0.1:5000/api/query", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          disease,
          intent: query,
          location,
          what_if: whatIf,
        }),
      });

      const result = await res.json();
      setData(result);

      if (whatIf) handleWhatIf();

    } catch (err) {
      console.error(err);
    }

    setLoading(false);
  };

  // =========================
  // WHAT-IF
  // =========================
  const handleWhatIf = async () => {
    if (!whatIf) return;

    setWhatIfLoading(true);

    try {
      const res = await fetch("http://127.0.0.1:5000/api/query", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          disease,
          intent: query,
          location,
          what_if: whatIf,
        }),
      });

      const result = await res.json();
      setWhatIfResult(result.insights);

    } catch (err) {
      console.error(err);
    }

    setWhatIfLoading(false);
  };

  return (
    <div className="container">

      {/* LEFT SIDEBAR */}
      <div className="left">
        <h2>Curalink X</h2>
        <p className="sub">AI Medical Research Copilot</p>

        <input
          placeholder="Filter by disease"
          value={disease}
          onChange={(e) => setDisease(e.target.value)}
        />

        <div className="card">
          <h3>Insight Filters</h3>
          <label><input type="checkbox" defaultChecked /> Publications</label>
          <label><input type="checkbox" defaultChecked /> Clinical trials</label>
          <label><input type="checkbox" defaultChecked /> Risk analysis</label>
        </div>

        <div className="card">
          <h3>Stats</h3>
          <p>Papers: {data?.meta?.total_papers || 0}</p>
          <p>Trials: {data?.meta?.total_trials || 0}</p>
          <p>Time: {data?.meta?.response_time_ms || 0} ms</p>
        </div>
      </div>

      {/* CENTER */}
      <div className="center">
        <h1>OpenAI reasoning copilot</h1>

        <textarea
          placeholder="Ask your medical research question..."
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />

        <button onClick={handleAnalyze}>
          {loading ? "Processing..." : "Send message"}
        </button>

        <div className="card">
          <h3>Structured query metadata</h3>

          <input placeholder="Disease" value={disease} onChange={(e)=>setDisease(e.target.value)} />
          <input placeholder="Location" value={location} onChange={(e)=>setLocation(e.target.value)} />
          <input placeholder="What-if treatment" value={whatIf} onChange={(e)=>setWhatIf(e.target.value)} />
        </div>
      </div>

      {/* RIGHT PANEL */}
      <div className="right">

        <div className="card">
          <h3>Dynamic Insights</h3>
          <p>{data?.insights || "Live synthesis"}</p>
        </div>

        <div className="card">
          <h3>Research papers</h3>
          {data?.publications?.map((p, i) => (
            <div key={i}>
              <b>{p.title}</b>
              <p>{p.year} • {p.source}</p>
            </div>
          ))}
        </div>

        <div className="card">
          <h3>Clinical trials</h3>
          {data?.clinical_trials?.map((t, i) => (
            <div key={i}>
              <b>{t.title}</b>
              <p>{t.status}</p>
            </div>
          ))}
        </div>

        <div className="card">
          <h3>What-if Analysis</h3>

          <input
            placeholder="e.g., diabetic patient"
            value={whatIf}
            onChange={(e) => setWhatIf(e.target.value)}
          />

          <button onClick={handleWhatIf}>
            {whatIfLoading ? "Simulating..." : "Simulate scenario"}
          </button>

          <p>{whatIfResult}</p>
        </div>

      </div>

    </div>
  );
}

export default App;
